#include <bits/stdc++.h>
using namespace std;

struct Team {
    string name;
    int points = 0;
    int goals = 0;
    int conceded = 0;
    int games = 0;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<tuple<string, string, int, int>> matches;
    map<string, int> id;
    vector<string> names;

    for (int i = 0; i < 5; ++i) {
        string a, b, score;
        cin >> a >> b >> score;

        int pos = score.find(':');
        int x = stoi(score.substr(0, pos));
        int y = stoi(score.substr(pos + 1));

        matches.emplace_back(a, b, x, y);
        names.push_back(a);
        names.push_back(b);
    }

    sort(names.begin(), names.end());
    names.erase(unique(names.begin(), names.end()), names.end());

    vector<Team> teams(names.size());
    for (int i = 0; i < (int)names.size(); ++i) {
        id[names[i]] = i;
        teams[i].name = names[i];
    }

    for (const auto &[a, b, x, y] : matches) {
        int u = id[a], v = id[b];

        teams[u].games++;
        teams[v].games++;
        teams[u].goals += x;
        teams[u].conceded += y;
        teams[v].goals += y;
        teams[v].conceded += x;

        if (x > y) {
            teams[u].points += 3;
        } else if (x < y) {
            teams[v].points += 3;
        } else {
            teams[u].points++;
            teams[v].points++;
        }
    }

    int berland = id["BERLAND"];
    int opponent = -1;

    for (int i = 0; i < (int)teams.size(); ++i) {
        if (i != berland && teams[i].games < 3) {
            opponent = i;
            break;
        }
    }

    auto qualifies = [&](int scored, int conceded) {
        vector<Team> current = teams;

        current[berland].points += 3;
        current[berland].goals += scored;
        current[berland].conceded += conceded;
        current[opponent].goals += conceded;
        current[opponent].conceded += scored;

        sort(current.begin(), current.end(), [](const Team &a, const Team &b) {
            if (a.points != b.points) return a.points > b.points;

            int diffA = a.goals - a.conceded;
            int diffB = b.goals - b.conceded;
            if (diffA != diffB) return diffA > diffB;

            if (a.goals != b.goals) return a.goals > b.goals;
            return a.name < b.name;
        });

        return current[0].name == "BERLAND" ||
               current[1].name == "BERLAND";
    };

    int bestDifference = INT_MAX;
    int bestScored = -1;
    int bestConceded = -1;

    for (int conceded = 0; conceded < 300; ++conceded) {
        for (int scored = conceded + 1; scored <= 300; ++scored) {
            if (qualifies(scored, conceded)) {
                int difference = scored - conceded;
                if (difference < bestDifference) {
                    bestDifference = difference;
                    bestScored = scored;
                    bestConceded = conceded;
                }
            }
        }
    }

    if (bestScored == -1) {
        cout << "IMPOSSIBLE\n";
    } else {
        cout << bestScored << ':' << bestConceded << '\n';
    }

    return 0;
}

